<?php require '../includes/functions.php';if(!is_admin())redirect('/movie-booking/admin/login.php');
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'';if($action==='add_movie'){$f=['title','director','language','duration','genre','release_date','description','ticket_price','status','trailer_url','cast_members'];$d=[];foreach($f as $x)$d[$x]=trim($_POST[$x]??'');db()->prepare('INSERT INTO movies(title,director,language,duration,genre,release_date,description,ticket_price,status,trailer_url,cast_members,poster) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$d['title'],$d['director'],$d['language'],$d['duration'],$d['genre'],$d['release_date'],$d['description'],$d['ticket_price'],$d['status'],$d['trailer_url'],$d['cast_members'],'assets/images/cinema-poster.svg']);flash('success','Movie added.');}elseif($action==='delete_movie'){db()->prepare('DELETE FROM movies WHERE id=?')->execute([(int)$_POST['id']]);flash('success','Movie deleted.');}elseif($action==='user_status'){db()->prepare("UPDATE users SET status=IF(status='active','blocked','active') WHERE id=?")->execute([(int)$_POST['id']]);flash('success','User status updated.');}elseif($action==='review'){db()->prepare('UPDATE reviews SET approved=1 WHERE id=?')->execute([(int)$_POST['id']]);flash('success','Review approved.');}elseif($action==='add_show'){db()->prepare('INSERT INTO shows(movie_id,screen_id,show_date,show_time,ticket_price) VALUES(?,?,?,?,?)')->execute([(int)$_POST['movie_id'],(int)$_POST['screen_id'],$_POST['show_date'],$_POST['show_time'],$_POST['ticket_price']]);flash('success','Show added.');}redirect('/movie-booking/admin/index.php?tab='.urlencode($_POST['tab']??'dashboard'));}
$tab=$_GET['tab']??'dashboard';$pdo=db();$stats=['Users'=>$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn(),'Movies'=>$pdo->query('SELECT COUNT(*) FROM movies')->fetchColumn(),'Bookings'=>$pdo->query("SELECT COUNT(*) FROM bookings WHERE status='confirmed'")->fetchColumn(),'Revenue'=>'₹'.number_format($pdo->query("SELECT COALESCE(SUM(total_amount),0) FROM bookings WHERE status='confirmed'")->fetchColumn())];$movies=$pdo->query('SELECT * FROM movies ORDER BY id DESC')->fetchAll();$users=$pdo->query('SELECT * FROM users ORDER BY id DESC')->fetchAll();$reviews=$pdo->query('SELECT r.*,u.name,m.title FROM reviews r JOIN users u ON u.id=r.user_id JOIN movies m ON m.id=r.movie_id ORDER BY r.created_at DESC')->fetchAll();$screens=$pdo->query('SELECT s.*,t.name theater FROM screens s JOIN theaters t ON t.id=s.theater_id')->fetchAll();$latest=$pdo->query('SELECT b.*,u.name,m.title FROM bookings b JOIN users u ON u.id=b.user_id JOIN shows s ON s.id=b.show_id JOIN movies m ON m.id=s.movie_id ORDER BY b.created_at DESC LIMIT 8')->fetchAll();$pageTitle='Admin dashboard';require '../includes/header.php';?>
<div class="container-fluid py-4 px-lg-5"><div class="d-flex justify-content-between align-items-center"><h1>Control room</h1><a class="btn btn-sm btn-outline-light" href="logout.php">Admin logout</a></div><div class="nav nav-pills gap-2 my-4"><?php foreach(['dashboard'=>'Dashboard','movies'=>'Movies','shows'=>'Shows','users'=>'Users','reviews'=>'Reviews'] as $k=>$v):?><a class="nav-link <?=$tab===$k?'active':''?>" href="?tab=<?=$k?>"><?=$v?></a><?php endforeach?></div><?php if($tab==='dashboard'):?><div class="row g-3"><?php foreach($stats as $k=>$v):?><div class="col-md-3"><div class="booking-panel"><small class="text-secondary"><?=$k?></small><h2><?=$v?></h2></div></div><?php endforeach?></div><div class="row mt-3"><div class="col-lg-7"><div class="booking-panel"><canvas id="revenueChart"></canvas></div></div><div class="col-lg-5"><div class="booking-panel"><h4>Latest bookings</h4><?php foreach($latest as $b):?><div class="border-bottom border-secondary-subtle py-2"><strong><?=e($b['title'])?></strong><br><small><?=e($b['name'])?> · <?=e($b['booking_code'])?> · ₹<?=$b['total_amount']?></small></div><?php endforeach?></div></div></div><script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script>new Chart(document.getElementById('revenueChart'),{type:'line',data:{labels:['Mon','Tue','Wed','Thu','Fri','Sat','Sun'],datasets:[{label:'Revenue',data:[2400,3800,2200,4500,3800,6200,5100],borderColor:'#fa2f7f',tension:.35}]}})</script><?php elseif($tab==='movies'):?><div class="row g-4"><div class="col-lg-4"><div class="booking-panel"><h4>Add movie</h4><form method="post" class="row g-2"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="add_movie"><input type="hidden" name="tab" value="movies"><?php foreach(['title'=>'Title','director'=>'Director','cast_members'=>'Cast','language'=>'Language','duration'=>'Duration','genre'=>'Genre','trailer_url'=>'Trailer URL'] as $n=>$l):?><div class="col-12"><input required name="<?=$n?>" class="form-control" placeholder="<?=$l?>"></div><?php endforeach?><div class="col-6"><input name="release_date" type="date" class="form-control"></div><div class="col-6"><input name="ticket_price" type="number" value="250" class="form-control"></div><div class="col-12"><textarea name="description" class="form-control" placeholder="Description"></textarea></div><div class="col-12"><select name="status" class="form-select"><option value="now_showing">Now showing</option><option value="upcoming">Upcoming</option></select></div><button class="btn btn-gradient">Add movie</button></form></div></div><div class="col-lg-8"><div class="booking-panel table-responsive"><table class="table table-dark"><thead><tr><th>Movie</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($movies as $m):?><tr><td><?=e($m['title'])?></td><td><?=e($m['status'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="delete_movie"><input type="hidden" name="tab" value="movies"><button name="id" value="<?=$m['id']?>" class="btn btn-sm btn-outline-danger" onclick="return confirm('Delete movie and its shows?')">Delete</button></form></td></tr><?php endforeach?></tbody></table></div></div></div><?php elseif($tab==='shows'):?><div class="booking-panel col-lg-6"><h4>Add show</h4><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="add_show"><input type="hidden" name="tab" value="shows"><div class="col-6"><select name="movie_id" class="form-select"><?php foreach($movies as $m):?><option value="<?=$m['id']?>"><?=e($m['title'])?></option><?php endforeach?></select></div><div class="col-6"><select name="screen_id" class="form-select"><?php foreach($screens as $s):?><option value="<?=$s['id']?>"><?=e($s['theater'])?> · <?=e($s['name'])?></option><?php endforeach?></select></div><div class="col-4"><input required type="date" name="show_date" class="form-control"></div><div class="col-4"><input required type="time" name="show_time" class="form-control"></div><div class="col-4"><input required type="number" name="ticket_price" value="250" class="form-control"></div><button class="btn btn-gradient">Create show</button></form></div><?php elseif($tab==='users'):?><div class="booking-panel table-responsive"><table class="table table-dark"><thead><tr><th>Name</th><th>Email</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td><?=e($u['status'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="user_status"><input type="hidden" name="tab" value="users"><button name="id" value="<?=$u['id']?>" class="btn btn-sm btn-outline-warning">Block/unblock</button></form></td></tr><?php endforeach?></tbody></table></div><?php else:?><div class="booking-panel table-responsive"><table class="table table-dark"><thead><tr><th>User</th><th>Movie</th><th>Rating</th><th>Review</th><th></th></tr></thead><tbody><?php foreach($reviews as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['title'])?></td><td><?=$r['rating']?>/5</td><td><?=e($r['review'])?></td><td><?php if(!$r['approved']):?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="review"><input type="hidden" name="tab" value="reviews"><button name="id" value="<?=$r['id']?>" class="btn btn-sm btn-success">Approve</button></form><?php endif?></td></tr><?php endforeach?></tbody></table></div><?php endif?></div><?php require '../includes/footer.php'; ?>
